func TestReviewAccess(t *testing.T) {
	db := openSeededStore(t)
	sdb := db.DB()

	// Members.
	mustExec(t, sdb, `INSERT INTO members(id, data, member_id, email) VALUES (?,?,?,?)`,
		"m1", `{}`, "m1", "alice@acme.com")
	mustExec(t, sdb, `INSERT INTO members(id, data, member_id, email) VALUES (?,?,?,?)`,
		"m2", `{}`, "m2", "stranger@acme.com")
	// Team t1, alice (m1) is a member.
	mustExec(t, sdb, `INSERT INTO teams(id, data, team_id, name) VALUES (?,?,?,?)`,
		"t1", `{}`, "t1", "Finance")
	mustExec(t, sdb, `INSERT INTO members_teams(id, members_id, data, parent_id) VALUES (?,?,?,?)`,
		"mt1", "m1", `{"teamId":"t1","name":"Finance"}`, "m1")
	// Resources.
	mustExec(t, sdb, `INSERT INTO workbooks(id, data, name) VALUES (?,?,?)`,
		"wbDirect", `{}`, "Direct Workbook")
	mustExec(t, sdb, `INSERT INTO workbooks(id, data, name) VALUES (?,?,?)`,
		"wbTeam", `{}`, "Team Workbook")
	mustExec(t, sdb, `INSERT INTO workbooks(id, data, name) VALUES (?,?,?)`,
		"wbStranger", `{}`, "Stranger Workbook")
	// Grants: alice direct on wbDirect; team t1 on wbTeam; stranger direct on wbStranger.
	mustExec(t, sdb, `INSERT INTO grants(id, data, inode_id, inode_type, member_id, permission) VALUES (?,?,?,?,?,?)`,
		"g1", `{}`, "wbDirect", "workbook", "m1", "edit")
	mustExec(t, sdb, `INSERT INTO grants(id, data, inode_id, inode_type, team_id, permission) VALUES (?,?,?,?,?,?)`,
		"g2", `{}`, "wbTeam", "workbook", "t1", "view")
	mustExec(t, sdb, `INSERT INTO grants(id, data, inode_id, inode_type, member_id, permission) VALUES (?,?,?,?,?,?)`,
		"g3", `{}`, "wbStranger", "workbook", "m2", "edit")

	rows, err := reviewAccess(sdb, "m1")
	if err != nil {
		t.Fatalf("reviewAccess: %v", err)
	}

	via := map[string]string{} // resourceName -> via
	for _, r := range rows {
		via[r.ResourceName] = r.Via
	}
	if via["Direct Workbook"] != "direct" {
		t.Errorf("Direct Workbook via = %q, want direct", via["Direct Workbook"])
	}
	if via["Team Workbook"] != "team:Finance" {
		t.Errorf("Team Workbook via = %q, want team:Finance", via["Team Workbook"])
	}
	// Negative: unrelated member's grant must NOT appear.
	if _, ok := via["Stranger Workbook"]; ok {
		t.Errorf("Stranger Workbook leaked into alice's access review")
	}
	if len(rows) != 2 {
		t.Errorf("expected 2 reachable resources, got %d: %+v", len(rows), rows)
	}

	// Member with no grants -> empty, not error.
	none, err := reviewAccess(sdb, "m2-no-grants")
	if err != nil {
		t.Fatalf("reviewAccess(empty): %v", err)
	}
	if len(none) != 0 {
		t.Errorf("expected 0 rows for member with no grants, got %d", len(none))
	}
}
